namespace {
using namespace material_fit;
int checks=0;
void check(bool ok,const char* m){++checks;if(!ok)throw std::runtime_error(m);}
template<class F>void rejects(F f){try{f();}catch(const std::exception&){++checks;return;}throw std::runtime_error("Unsafe spectral input accepted");}
double gaussian(double x,double center,double sigma){return std::exp(-.5*std::pow((x-center)/sigma,2));}
SpectralModel makeModel(int n=81,double step=5){SpectralModel m;for(int i=0;i<n;++i){const double nm=400+step*i;m.wavelengths.push_back(nm);m.base.push_back(.12+.5*gaussian(nm,430,60));m.dyes.push_back({.02+gaussian(nm,640,45),.01+gaussian(nm,545,35),.015+gaussian(nm,435,40)});m.weights.push_back({gaussian(nm,635,24),gaussian(nm,545,22),gaussian(nm,445,23)});}return m;}
// Independent long-double Beer-Lambert oracle: no production log-sum-exp
// or analytic Jacobian used to generate the expected instrument values.
Triple oracle(const SpectralModel& m,const Triple& a){Triple out{};for(int c=0;c<3;++c){long double light=0,total=0;for(size_t l=0;l<m.base.size();++l){long double d=m.base[l];for(int k=0;k<3;++k)d+=static_cast<long double>(a[k])*m.dyes[l][k];light+=m.weights[l][c]*std::pow(10.L,-d);total+=m.weights[l][c];}out[c]=static_cast<double>(-std::log10(light/total));}return out;}
Triple linearCounterfactual(const SpectralModel& m,const Triple& y){const auto p=project(m,{});auto j=p.jacobian;Triple rhs{};for(int c=0;c<3;++c)rhs[c]=y[c]-p.density[c];for(int k=0;k<3;++k){const double d=j[k][k];for(int c=k;c<3;++c)j[k][c]/=d;rhs[k]/=d;for(int r=0;r<3;++r)if(r!=k){const auto f=j[r][k];for(int c=k;c<3;++c)j[r][c]-=f*j[k][c];rhs[r]-=f*rhs[k];}}return rhs;}
void write(const QString& file,const QJsonObject& o){QFile f(file);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Cannot create owned spectral fixture");const auto b=QJsonDocument(o).toJson();check(f.write(b)==b.size(),"Incomplete spectral fixture write");}
QByteArray read(const QString& file){QFile f(file);check(f.open(QIODevice::ReadOnly),"Cannot read spectral evidence");return f.readAll();}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
    check(argc>=2,"Expected CLI path");const bool broken=app.arguments().contains("--linear-counterfactual");const auto model=makeModel();
    for(const auto c:{.1,.8,1.7,3.5})for(const auto m:{.1,.8,1.7,3.5})for(const auto y:{.1,.8,1.7,3.5}){const Triple truth{c,m,y};const auto target=oracle(model,truth);const auto forward=project(model,truth);for(int k=0;k<3;++k)check(std::abs(forward.density[k]-target[k])<1e-12,"Forward spectral integral disagrees with independent oracle");const auto result=invert(model,target);const auto recovered=broken?linearCounterfactual(model,target):result.amounts;check(result.identifiable&&result.max_abs<1e-7,"Known spectral inverse failed residual/conditioning");for(int k=0;k<3;++k)check(std::abs(recovered[k]-truth[k])<1e-5,"Known CMY recovery failed (linear matrix is not spectral inversion)");}
    const Triple probe{.4,.5,.8};const auto projected=project(model,probe);for(int k=0;k<3;++k){auto plus=probe,minus=probe;plus[k]+=1e-5;minus[k]-=1e-5;const auto a=oracle(model,plus),b=oracle(model,minus);for(int c=0;c<3;++c)check(std::abs(projected.jacobian[c][k]-(a[c]-b[c])/2e-5)<1e-8,"Analytic spectral Jacobian is incorrect");}
    auto scaled=model;for(auto& row:scaled.weights)for(int k=0;k<3;++k)row[k]*=std::pow(10.,k+2);const auto scaleProjection=project(scaled,probe);for(int c=0;c<3;++c)check(std::abs(scaleProjection.density[c]-projected.density[c])<1e-12,"Instrument gain changed normalized density");
    auto signedDyes=model;for(auto& row:signedDyes.dyes)row[1]-=.08;const auto signedExpected=oracle(signedDyes,probe),signedActual=project(signedDyes,probe).density;for(int c=0;c<3;++c)check(std::abs(signedExpected[c]-signedActual[c])<1e-12,"Signed surrogate dye samples were silently clipped");
    const auto lower=lowerDensityBounds(signedDyes);for(double a:{0.,.4,2.,8.})for(double b:{0.,1.,8.}){const auto density=oracle(signedDyes,{a,b,8-a});for(int c=0;c<3;++c)check(lower[c]<=density[c]+1e-12,"Analytical lower density bound excludes a known feasible point");}
    auto grey=model;for(auto& b:grey.base)b=1.25;for(auto& d:grey.dyes)d={0,0,0};const auto greyProjection=project(grey,{});for(const auto d:greyProjection.density)check(std::abs(d-1.25)<1e-12,"Uniform optical density is not conserved");const auto rank=invert(grey,{1.25,1.25,1.25});check(!rank.identifiable&&rank.max_abs<1e-12,"Rank-deficient inverse was certified because it reconstructs");const auto impossible=invert(grey,{.5,.5,.5});check(impossible.max_abs>.7&&!impossible.identifiable,"Impossible below-base target was silently offset/clipped");
    auto invalid=model;invalid.weights[0][0]=-1;rejects([&]{project(invalid,probe);});invalid=model;invalid.base.pop_back();rejects([&]{project(invalid,probe);});invalid=model;invalid.wavelengths[1]=invalid.wavelengths[0];rejects([&]{project(invalid,probe);});invalid=model;invalid.dyes[0][0]=std::numeric_limits<double>::quiet_NaN();rejects([&]{project(invalid,probe);});invalid=model;for(auto& row:invalid.weights)row[1]=0;rejects([&]{project(invalid,probe);});rejects([&]{invert(model,{-1,1,1});});rejects([&]{project(model,{9,0,0});});
    auto measured=makeModel(301,1);QJsonArray wl,base,operatorWl,axis;std::array<QJsonArray,3> dyes,weights,targets,ssf;
    // Explicit synthetic operator, intentionally wider than dye coverage.
    for(int nm=400;nm<=770;nm+=10){operatorWl.append(nm);for(int c=0;c<3;++c)weights[c].append(gaussian(nm,c==0?635:c==1?545:445,c==0?24:c==1?22:23));}
    for(int i=0;i<301;++i){const double nm=400+i;wl.append(nm);base.append(measured.base[i]);for(int c=0;c<3;++c){dyes[c].append(measured.dyes[i][c]);const int lo=int((nm-400)/10),hi=std::min(lo+1,37);const double fraction=(nm-400-lo*10)/10;measured.weights[i][c]=weights[c][lo].toDouble()*(1-fraction)+weights[c][hi].toDouble()*fraction;ssf[c].append(i<5||i>295?QJsonValue():QJsonValue(-1.+gaussian(nm,450+c*90,50)));}}
    for(int i=0;i<31;++i){axis.append(-3+i*.1);const auto density=oracle(measured,{.02+i*.04,.03+i*.03,.01+i*.05});for(int c=0;c<3;++c)targets[c].append(density[c]);}
    const QJsonObject curves{{"source","Owned synthetic curves, not a photographic measurement"},{"char_curves",QJsonObject{{"log_exposure_units","log lux-seconds"},{"log_exposure",axis},{"statusM_density",QJsonObject{{"R",targets[0]},{"G",targets[1]},{"B",targets[2]}}}}},{"spectral",QJsonObject{{"wavelength_nm",wl},{"dmin",base}}}};
    const QJsonObject dye{{"source","Owned analytic synthetic dyes"},{"shared_full_curves",QJsonObject{{"wavelength_nm",wl},{"cyan",dyes[0]},{"magenta",dyes[1]},{"yellow",dyes[2]}}}};
    const QJsonObject response{{"source","Owned synthetic operator; NOT ISO Status M"},{"wavelength_nm",operatorWl},{"responsivity_linear_peak1",QJsonObject{{"red",weights[0]},{"green",weights[1]},{"blue",weights[2]}}}};
    const QJsonObject sensitivity{{"source","Owned sensitivity coverage fixture"},{"measurement_note","Synthetic test only; no calibrated exposure anchor"},{"wavelength_nm",wl},{"log_sensitivity",QJsonObject{{"cyan",ssf[0]},{"magenta",ssf[1]},{"yellow",ssf[2]}}}};
    const auto report=liftDocument(curves,dye,response,sensitivity);check(report["mathematical_fit_passed"].toBool()&&!report["profile_ready"].toBool(),"Synthetic report failed or became installable Profile");check(report["rows"].toArray().size()==31&&report["sensitivity_audit"].toObject()["unknown_samples_are_not_zero"].toBool(),"Measurements or missing-support diagnostics dropped");check(QJsonDocument(report).toJson()==QJsonDocument(liftDocument(curves,dye,response,sensitivity)).toJson(),"Spectral report is nondeterministic");rejects([&]{MaterialLibrary::validateProfile(report);});
    const auto omitted=report["integration"].toObject()["omitted_operator_weight_fraction_RGB"].toArray();for(int c=0;c<3;++c){long double full=0,tail=0;for(int nm=400;nm<=770;++nm){const int lo=std::min((nm-400)/10,36);const long double t=(nm-400-lo*10)/10.L;const long double w=weights[c][lo].toDouble()*(1-t)+weights[c][lo+1].toDouble()*t;full+=w;if(nm>700)tail+=w;}check(std::abs(omitted[c].toDouble()-double(tail/full))<1e-14,"Omitted operator area is not measured on the actual 1 nm integration grid");}
    auto incompatible=dye;auto table=incompatible["shared_full_curves"].toObject();auto badWl=wl;badWl[0]=399;table["wavelength_nm"]=badWl;incompatible["shared_full_curves"]=table;rejects([&]{liftDocument(curves,incompatible,response,sensitivity);});
    auto huge=response;auto hugeAxis=operatorWl;hugeAxis[hugeAxis.size()-1]=1e100;huge["wavelength_nm"]=hugeAxis;rejects([&]{liftDocument(curves,dye,huge,sensitivity);});
    auto missingSensitivity=sensitivity;auto missingChannels=sensitivity["log_sensitivity"].toObject();auto gap=ssf[0];gap[100]=QJsonValue();missingChannels["cyan"]=gap;missingSensitivity["log_sensitivity"]=missingChannels;const auto gapAudit=liftDocument(curves,dye,response,missingSensitivity)["sensitivity_audit"].toObject();check(gapAudit["channels"].toObject()["cyan"].toObject()["internal_missing_samples"].toBool()&&!gapAudit["exposure_anchor_calibrated"].toBool(),"Internal sensitivity gaps were filled or certified calibrated");
    QTemporaryDir owned;check(owned.isValid(),"Cannot own spectral CLI fixtures");const auto cp=owned.filePath("curves.json"),dp=owned.filePath("dyes.json"),rp=owned.filePath("operator.json"),sp=owned.filePath("ssf.json"),output=owned.filePath("report.json");write(cp,curves);write(dp,dye);write(rp,response);write(sp,sensitivity);
    const auto run=[&](QStringList args){QProcess process;process.start(app.arguments()[1],args);check(process.waitForFinished(30000)&&process.exitStatus()==QProcess::NormalExit,"Spectral CLI crashed/timed out");return process.exitCode();};
    const QStringList args{"--spectral","--input",cp,"--dyes",dp,"--responsivity",rp,"--sensitivity",sp,"--output",output};check(run(args)==0,"Synthetic spectral CLI failed");const auto original=read(output);const auto cli=QJsonDocument::fromJson(original).object();check(cli["format"]=="SpektraLab.SpectralLift"&&cli["inputs"].toObject()["responsivity"].toObject()["sha256"]==QString::fromLatin1(QCryptographicHash::hash(read(rp),QCryptographicHash::Sha256).toHex()),"Explicit operator provenance/hash missing");check(run(args)==1&&read(output)==original,"Spectral CLI overwrote an existing report");
    const auto missing=owned.filePath("missing.json");check(run({"--spectral","--input",cp,"--output",missing})==1&&!QFile::exists(missing),"Missing spectral dependencies silently filled");
    auto impossibleCurves=curves;auto chart=curves["char_curves"].toObject();auto impossibleTargets=chart["statusM_density"].toObject();auto r=targets[0];r[0]=0;impossibleTargets["R"]=r;chart["statusM_density"]=impossibleTargets;impossibleCurves["char_curves"]=chart;const auto ip=owned.filePath("unreachable.json"),failedOutput=owned.filePath("failed-report.json");write(ip,impossibleCurves);auto badArgs=args;badArgs[badArgs.indexOf(cp)]=ip;badArgs[badArgs.indexOf(output)]=failedOutput;check(run(badArgs)==3,"Failed reconstruction was certified or discarded as a parser error");const auto failed=QJsonDocument::fromJson(read(failedOutput)).object();check(!failed["mathematical_fit_passed"].toBool()&&failed["rows"].toArray().size()==31&&failed["summary"].toObject()["rejected_rows"].toInt()>0,"Failed targets disappeared from report");
    const auto certified=liftDocument(impossibleCurves,dye,response,sensitivity,true);const auto certificate=certified["feasibility_certificate"].toObject();check(certified["version"]==2&&certificate["proved_unreachable_rows"].toArray().size()>0&&!certified["profile_ready"].toBool(),"Unreachable below-bound measurement was not independently certified");
    auto certifyArgs=badArgs;certifyArgs.append("--certify-bounds");certifyArgs[certifyArgs.indexOf(failedOutput)]=owned.filePath("certified.json");check(run(certifyArgs)==3,"Certificate CLI falsely passed real quality gate");check(QJsonDocument::fromJson(read(owned.filePath("certified.json"))).object()["feasibility_certificate"].isObject(),"Certificate missing from explicit v2 output");
    std::cout<<"Spectral lift: "<<checks<<" checks; independent transmission/Jacobian, nonlinear CMY recovery, rank/bounds, explicit operator/provenance and safe CLI refusal passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
